const VARIANTS=5;

// Build variant i of a country: same city/zip (valid), different name, street number and unit
function makeVariant(c,i){if(!i)return {...c};
 const num=m=>m.replace(/(\d+)(?!.*\d)/,(n)=>String(+n+i*2));
 return {...c,fullName:c.names[i%c.names.length],line1:/\d/.test(c.line1)?num(c.line1):c.line1,line2:['Floor 1','Apt 2','Unit 3','Suite 4','Floor 5'][i%5]};}
function getAddr(code,i,custom){const c=COUNTRIES.find(x=>x.code===code);if(!c)return null;
 let cu=(custom||{})[code];if(cu&&!Array.isArray(cu))cu=[cu];return {...makeVariant(c,i),...((cu||[])[i]||{})};}
